        '공격 후 적 생명력 20% 미만 즉시 처치(보스 10%)': '攻擊後敵人生命低於 20% 時立即擊殺（首領 10%）',
        '회피 150당 연속 타격 +1%p(최대 +15%p), 방어도 500당 치명타 확률 +1%p(최대 +10%p)': '每 150 閃避連續打擊 +1%p（最多 +15%p），每 500 護甲暴擊機率 +1%p（最多 +10%p）',
