        '막기 확률 및 비껴내기 확률 판정에 행운 적용(2회 굴려 유리한 값 선택)': '格擋與偏斜機率判定為幸運（擲兩次取較優值）',
        '치명타 피해 배율 +66%, 치명타 확률 -6%p': '暴擊傷害倍率 +66%，暴擊機率 -6%p',
        '이동 시 흐릿함 상태 부여: 이동 속도 +20%, 치명타 피해 배율 +25%, 회피 20% 증폭. 피해를 받으면 해제': '移動時獲得模糊狀態：移動速度 +20%，暴擊傷害倍率 +25%，閃避總增 20%。受到傷害時解除',
        '치명타 발생 시 5초간 대상 받는 피해 +2% (개별 대상, 최대 10중첩, 적 상태이상에 표시)': '暴擊時目標 5 秒內受到的傷害 +2%（按目標計，最多 10 層，顯示在敵人異常狀態中）',
        '물리 피해 감소 무시 +25%, 저항 관통 +25%, 피해 8% 감폭': '無視物理減傷 +25%，抗性穿透 +25%，傷害總降 8%',
