        '치명타 피해 배율 20% 증폭 및 회피 20% 증폭': '暴擊傷害倍率總增 20% 且閃避總增 20%',
        '이동 속도 15% 증폭, 방어도/에너지 보호막 0': '移動速度總增 15%，護甲/能量護盾為 0',
