        '투사체 스킬 타겟 수 +1, 타겟마다 피해 4% 증폭': '投射物技能目標數 +1，每個目標傷害總增 4%',
        '피격되지 않은 시간 1초마다 치명타 확률 +3%p (피격 시 초기화)': '每未受擊 1 秒暴擊機率 +3%p（受擊時重置）',
        '공격 속도와 이동 속도 상호 12% 효율 보정, 최대 생명력 -15%': '攻擊速度與移動速度互相以 12% 效率修正，最大生命 -15%',
