        '모든 원소 저항 +15%, 원소 저항 최대치 +3%, 카오스 저항 -10%': '所有元素抗性 +15%，元素抗性上限 +3%，混沌抗性 -10%',
        '에너지 보호막 재생이 끊기지 않음, 최대 생명력 -15%': '能量護盾恢復不會中斷，最大生命 -15%',
