        '카오스 저항이 가장 높은 원소 저항의 50%만큼 상승, 카오스 저항만큼 원소 최종 피해 증가': '混沌抗性提高最高元素抗性的 50%，元素最終傷害按混沌抗性提高',
        '저항 관통 +20%, 치명타 피해 배율 -25%': '抗性穿透 +20%，暴擊傷害倍率 -25%',
        '화/냉/번 동시 사용 시 최종 피해 5% 증폭, 상태이상 강도는 최종 피해의 1.5배에 비례': '同時使用火焰/冰霜/閃電時最終傷害總增 5%，異常狀態強度與最終傷害的 1.5 倍成比例',
