        '공허 리바이어던 새끼': '虛空利維坦幼崽',
        '극심한 수압 구간에서만 모습을 드러내는 전설의 새끼 괴어입니다.': '只在極端水壓區域現身的傳說幼年怪魚。',
        '해류군주 비단잉어': '海流君主錦鯉',
        '가장 깊은 해류가 휘몰아치는 구간에서만 모습을 드러내는 군주급 어종입니다.': '只在最深海流翻湧的區域現身的君主級魚種。',
        '무지갯빛 공포': '虹色恐怖',
        '빛조차 닿지 않는 압사 구간 깊숙이서 발견되는 변종 심해어입니다.': '在連光也無法到達的壓潰區深處發現的變種深海魚。',
        '리바이어던 본체': '利維坦本體',
