        '“…허나 어째서 우물 바닥에 버려졌던 첫 번째 파편이, 모루 위의 완성작보다 더 날카롭게 울리는가.”': '「……可為何被丟棄在井底的第一塊碎片，鳴響得比鐵砧上的完成之作更加鋒利？」',
        '(벼림꾼 오르가의 모루터 폐기 장부 제7항)': '（鍛造師奧爾加的鐵砧廢棄帳簿第 7 項）',
        '잔향체, 아스트라': '餘響體，阿斯特拉',
