        '다섯 별의 잔향이 뭉친 아스트라를 쓰러뜨린 기록입니다.': '擊敗由五顆星的餘響凝聚而成的阿斯特拉的記錄。',
        '“다섯 은하의 군주가 소멸한 궤도 위에, 별들의 유언이 뭉쳐 하나의 잔향체가 깨어났다.”': '「在五大星系君主消亡的軌道上，群星的遺言凝聚，一個餘響體甦醒了。」',
