        '“지하계의 끝은 암반이 아니라 세계수의 뿌리를 아래에서 태우던 거대한 지핵(地核)의 심장이었다.”': '「地下界的盡頭不是岩層，而是自下方灼燒世界樹之根的巨大地核之心。」',
        '“모르그란의 용광로가 식자, 뿌리 아래를 짓누르던 영겁의 침묵에 첫 균열이 갔다.”': '「莫格蘭的熔爐冷卻之時，壓在根下的永劫寂靜第一次出現了裂痕。」',
        '무광해의 포식자, 탈라사': '無光之海的掠食者，塔拉薩',
