        '“빛이 닿지 않는 천 미터 해구(海溝)에서, 뿌리가 흘린 썩은 수액을 먹고 자란 고대 포식자의 기록.”': '「在光照不到的千公尺海溝中，以根部流出的腐爛樹液為食長大的古代掠食者的記錄。」',
