        '연쇄 투척': '連鎖投擲',
        '부채꼴 연사': '扇形連射',
        '관통 후 지연 폭발': '穿透後延遲爆炸',
        '곡사 투척': '曲射投擲',
        '공격 속도 ×1.2': '攻擊速度 ×1.2',
