        '치명타 확률 +15%': '暴擊率 +15%',
        '치명타 적중 피해 30% 증폭': '暴擊命中傷害增幅30%',
        '가장 가까운 적 하나를 가격합니다. 레벨업당 피해 배율 +5%, 공격 속도 +1%가 적용됩니다.': '攻擊最近的一個敵人。每次升級傷害倍率 +5%，攻擊速度 +1%。',
        'X자로 엇갈리게 두 번 벱니다. 두 번 모두 같은 피해를 줍니다.': '交叉成X形斬擊兩次。兩次造成相同傷害。',
        '총 피해의 62%를 본 타격으로 주고, 0.42초 후 나머지 38%를 여진으로 가합니다.': '主命中造成總傷害的62%，0.42秒後餘震造成剩餘38%。',
        '피의 바늘이 앞 2칸을 꿰뚫어 적 셋을 찌릅니다. 이 룬으로 준 피해의 흡혈은 즉시 회복됩니다.': '血針刺穿前方2格，刺中三名敵人。此符文造成傷害的吸血立即恢復。',
        '생명력이 가득 찬 적에게 35% 증폭된 피해를 주는 선제 처형기입니다.': '對滿生命敵人造成35%增幅傷害的先手處決技。',
        '0.08초마다 회전하며 그 순간 서 있는 칸 둘레의 아직 베지 않은 적을 하나씩 벱니다(움직이는 중에도 이어짐). 자신을 포위한 적 한 기당 피해가 4%씩 최대 28% 증폭됩니다.': '每0.08秒旋轉一次，斬擊當時所站格子周圍尚未斬過的一名敵人（移動中也持續）。每有一名敵人包圍自己，傷害增幅4%，最多28%。',
        '첫 대상을 강하게 타격한 뒤 연쇄됩니다. 도약마다 피해가 12% 감소하고 감전 확률이 25% 증가합니다.': '重擊第一個目標後連鎖。每次跳躍傷害降低12%，感電機率提高25%。',
        '매우 빠른 빙창이 적 둘을 꿰뚫습니다. 추가 치명타는 룬 레벨에 따라 성장합니다.': '極快的冰槍刺穿兩名敵人。額外暴擊隨符文等級成長。',
        '점화 확률 +25%. 점화 중인 적에게 주는 적중 피해가 15% 증폭됩니다.': '點燃機率 +25%。對點燃中的敵人造成的命中傷害增幅15%。',
        '중독 확률 +30%. 중독된 적을 적중하면 65% 확률로 다른 적 하나에게 중독을 전파합니다.': '中毒機率 +30%。命中中毒敵人時有65%機率將中毒傳播給另一名敵人。',
        '거리가 한 칸 멀어질 때마다 피해가 6%씩 최대 30% 증폭되는 관통 번개 창입니다.': '每遠離一格，傷害增幅6%、最多30%的穿透閃電槍。',
        '각 원본 타겟의 처치 후 남은 피해가 다른 적에게 이어지고, 전달 피해가 다시 초과되면 연속 관통합니다. 전이될 때마다 전달 피해가 80%로 감쇄합니다.': '擊殺每個原始目標後的剩餘傷害轉移到其他敵人，若轉移傷害再次溢出則繼續穿透。每次轉移時傳遞傷害衰減至80%。',
        '틈 닫힘': '裂隙閉合',
        '허공을 3칸 길이로 갈라 공허 틈을 엽니다. 틈이 닫히며 둘레 2칸 안 적을 끌어당겨 피해의 50%를 한 번 더 줍니다.': '將虛空撕開3格長的裂隙。裂隙閉合時拉拽周圍2格內的敵人，再造成一次50%傷害。',
        '크게 외쳐 자신을 중심으로 마름모 진동파를 퍼뜨립니다. 생명력과 재생력을 피해로 바꿉니다.': '大聲呼喊，以自身為中心擴散菱形震盪波。將生命與回復力轉化為傷害。',
        '십자 범위에 낮은 부패의 불길을 남깁니다. 공격력 없이 생명력/초과 화염 저항 계수로 화염 지속 피해를 퍼뜨립니다. 이미 타는 적에게 다시 맞히면 남은 피해를 한 번에 주고 둘레 2칸에 70%로 터지며 가까운 적 셋에게 옮겨 붙습니다. 타는 채 죽어도 터집니다.': '在十字範圍留下低矮的腐敗之火。不依賴攻擊力，以生命/超額火焰抗性係數擴散火焰持續傷害。再次命中已燃燒的敵人時一次性造成剩餘傷害，並在周圍2格以70%爆炸，蔓延到最近的三名敵人。燃燒中死亡也會爆炸。',
        '서리 균열': '霜裂',
        '침식 확산': '侵蝕擴散',
        '침식 완성': '侵蝕完成',
        '서리가 중심에서 마름모 범위로 3단계 확산합니다. 반복 적용할 때마다 최대 5중첩까지 냉기 지속 피해가 14%, 둔화가 4%씩 누적됩니다.': '霜從中心以菱形範圍分3階段擴散。每次重複施加最多疊加5層，每層累積14%冰霜持續傷害與4%減速。',
        '전방의 칸을 0.16초 간격으로 천천히 훑는 냉기 파동 주문입니다.': '以0.16秒間隔緩慢掃過前方格子的冰霜波動法術。',
        '적중 시 40% 확률로 뇌운을 적용해 0.6초마다 적중 피해의 22%를 4회 가합니다.': '命中時有40%機率施加雷雲，每0.6秒造成命中傷害的22%，共4次。',
        '2칸 이내의 적에게 차례로 감염이 건너갑니다. 감염된 적이 처치되면 남은 지속 피해를 다른 적 하나에게 이전합니다.': '感染依次跳向2格內的敵人。被感染的敵人死亡時，剩餘持續傷害轉移給另一名敵人。',
        '전방 좁은 부채꼴(20도 간격)로 화살 5발을 네 번에 나눠 쏩니다(2, 1, 1, 1발). 가운데 화살은 대상을 겨누고, 옆 화살은 각각 기본 타격 피해의 40%로 그 방향의 다른 적을 맞힙니다.': '向前方狹窄扇形（間隔20度）分四次射出5支箭（2、1、1、1支）。中間的箭瞄準目標，兩側的箭各以基礎命中傷害的40%擊中該方向的其他敵人。',
        '관통 후 0.25초 뒤 타격 피해의 25%로 폭발하며 점화 확률이 25% 증가합니다.': '穿透後0.25秒以命中傷害的25%爆炸，點燃機率提高25%。',
        '적이 잃은 생명력 비율만큼 최대 30% 피해가 증가하며, 생명력 15% 미만인 일반 적을 처형합니다.': '傷害按敵人已損失生命比例提高，最多30%，並處決生命低於15%的普通敵人。',
        '중심 압축': '中心壓縮',
        '넓은 중력장으로 적을 중심에 1칸 끌어당긴 뒤, 0.32초 후 좁은 중심부를 압축합니다.': '以寬廣的重力場將敵人向中心拉1格，0.32秒後壓縮狹窄的中心區。',
        '목표 지역에 폭풍핵을 남겨 0.26초 간격으로 타격 피해의 34%를 3회 줍니다.': '在目標區域留下風暴核，以0.26秒間隔造成命中傷害的34%，共3次。',
        '빙결 파편 창을 꿰뚫어 쏘는 냉기 주문입니다. 냉각된 적에게 적중 시 냉각을 소모해 20% 증폭된 피해를 주고, 동결된 적에게 적중 시 동결을 소모해 40% 증폭된 피해를 줍니다.': '射出穿透冰凍碎片之槍的冰霜法術。命中受冷卻的敵人時消耗冷卻造成20%增幅傷害，命中被冰凍的敵人時消耗冰凍造成40%增幅傷害。',
        '첫 적을 맞힌 번개가 그 적 주변 3칸의 적에게 동시에 갈라집니다. 감전 확률이 20% 증가하며, 적중 시 50% 확률로 0.18초 뒤 타격 피해의 25%인 낙뢰가 떨어집니다.': '擊中第一個敵人的閃電同時分叉至其周圍3格內的敵人。感電機率提高20%，命中時有50%機率在0.18秒後落下造成命中傷害25%的落雷。',
