        '무기 피해 대신 주문 내장 화염 피해로 작은 유성을 빠르게 떨어뜨립니다. 폭발한 자리에 불타는 지대가 2.4초 동안 남아 0.4초마다 안의 적에게 타격 피해의 10%를 주며(6회), 첫 불길은 점화 확률이 100%입니다.': '以內建法術火焰傷害代替武器傷害，快速落下小流星。爆炸處留下燃燒地帶持續2.4秒，每0.4秒對其中敵人造成命中傷害的10%（6次），首次火焰點燃機率為100%。',
