        '가장 밀집된 목표 지역에 번개 각인을 설치합니다. 0.46초 뒤 십자 범위가 폭발하며 감전 확률이 20% 증가합니다.': '在最密集的目標區域設置閃電刻印。0.46秒後十字範圍爆炸，感電機率提高20%。',
        '최대 6칸 안의 적 옆으로 점멸해 베어냅니다. 같은 칸을 반복 왕복하지 않으며 낮은 공격 속도로 재사용을 제한합니다.': '閃現到最多6格內敵人身旁斬擊。不會在同一格反覆往返，並以較低攻擊速度限制重複使用。',
