        '아래에서 위로 베어 올려 맞은 적을 0.42초 띄웁니다. 떠 있는 동안 적은 움직이지도 공격하지도 못합니다.': '由下向上斬擊，將命中的敵人擊飛0.42秒。浮空期間敵人無法移動或攻擊。',
        '앞으로 3칸 돌진하며 부딪친 적 셋을 밀어냅니다.': '向前衝鋒3格，擊退撞到的三名敵人。',
        '4칸 안 적 앞으로 뛰어올라 내려찍어, 착지 둘레의 적 넷을 칩니다.': '跳向4格內的敵人並砸下，攻擊落點周圍的四名敵人。',
        '앞으로 공중제비를 돌며 2칸 나아가, 착지와 함께 앞을 크게 내려벱니다.': '向前翻滾前進2格，落地同時向前大幅下斬。',
        '무기를 치켜들었다 내려치며 앞쪽으로 넓게 불길을 터뜨려 적을 밀어냅니다.': '舉起武器砸下，向前方大範圍爆出火焰擊退敵人。',
        '무기 끝으로 바닥을 긁어 불꽃을 일으킨 뒤 올려 베어, 바닥을 타고 달리는 화염 검기를 5칸 날립니다.': '用武器尖端刮地起火後上斬，送出沿地奔馳5格的火焰劍氣。',
        '불씨 폭발': '火種爆炸',
        '친 자리에 불씨를 심고 0.3초 뒤 주변까지 폭발합니다. 본 타격 55%, 폭발 45%.': '在擊中處埋下火種，0.3秒後向周圍爆炸。主命中55%，爆炸45%。',
        '무기를 높이 들어 몸 둘레 2칸에 정전기를 일으켜 0.22초마다 4번 번개 피해를 줍니다(한 번에 30%).': '高舉武器，在身周2格引發靜電，每0.22秒造成4次閃電傷害（每次30%）。',
        '빛의 단두대': '光之斷頭台',
        '시전하면 둘레 2칸 안 적 넷의 머리 위에 빛의 단두대가 나타나 벼락과 함께 칼날이 떨어집니다.': '施放時，周圍2格內四名敵人頭頂出現光之斷頭台，刀刃隨雷霆落下。',
        '번개가 되어 적 사이를 순간이동하며 6번 벱니다. 처음엔 5칸 안의 적에게, 그다음은 4칸 안의 아직 안 벤 적에게 차례로 건너가고, 혼자 남은 적은 좌우를 오가며 다시 벱니다.': '化為閃電在敵人之間瞬移並斬擊6次。先跳向5格內的敵人，再依次跳向4格內尚未斬過的敵人，只剩一名敵人時左右往返再次斬擊。',
        '얼음 안개가 서린 칼로 정면을 넓게 벱니다. 냉각 확률 +25%.': '以纏繞冰霧的刀刃向正面大範圍斬擊。冷卻機率 +25%。',
        '얼음 칼날': '冰刃',
        '얼음 파동': '冰波',
        '몸을 한 바퀴 돌리며 둘레를 육각으로 꺾이는 얼음 베기로 벱니다. 꼭짓점마다 얼음 결정이 맺혔다 떨어지고, 바닥에 눈꽃 결정진이 그려지며 2칸까지 퍼지는 투명한 얼음 파동이 한 번 더 칩니다(30%).': '旋身一周，以折成六角形的冰斬斬擊周圍。每個頂點凝結冰晶落下，地面繪出雪花結晶陣，擴散至2格的透明冰波再擊一次（30%）。',
        '내리찍기': '下砸',
        '얼음 기둥': '冰柱',
        // ── 2026-11-04 표에서 넣음(w2b07-zh-TW.json) ──
        '바닥을 내리찍으면 0.26초 뒤 앞 3칸과 그 위아래 한 줄을 따라 얼음 기둥이 솟아 적을 칩니다. 내리찍기 45%, 얼음 기둥 55%.': '砸向地面後0.26秒，沿前方3格及其上下一排湧出冰柱攻擊敵人。下砸45%，冰柱55%。',
        '타오르는 바닥': '燃燒地面',
        '외침과 함께 둘레가 터지고(60%), 2칸 안 바닥이 1.2초 동안 타오릅니다(10%씩 4번).': '隨呼喊周圍爆裂（60%），2格內地面燃燒1.2秒（每次10%，共4次）。',
        '앞으로 내지른 냉기 파동이 앞 4칸과 그 위아래 한 줄로 퍼지며 닿는 적부터 맞습니다.': '向前推出的冰霜波動擴散至前方4格及其上下一排，先觸及的敵人先被命中。',
        '하늘로 화살을 쏘아 올려 7칸 안 대상 둘레에 화살비를 내립니다. 떨어질 때 100%, 0.22초마다 30%씩 4번 더.': '向天射箭，在7格內目標周圍降下箭雨。落下時100%，之後每0.22秒再造成30%，共4次。',
        '공격형 소환수 룬. 상하좌우로 불꽃 꼬리가 달린 화염 위습 정령을 소환합니다. 위습이 불덩이를 포물선으로 던져 화염 피해를 줍니다.': '攻擊型召喚符文。召喚上下左右帶有火焰尾巴的火焰鬼火精靈。鬼火以拋物線投擲火球造成火焰傷害。',
        '공격형 소환수 룬. 얼음 수정 모양의 냉기 위습 정령을 소환합니다. 위습이 얼음 조각을 곧게 던져 냉기 피해를 줍니다.': '攻擊型召喚符文。召喚冰晶形狀的冰霜鬼火精靈。鬼火直線投擲冰片造成冰霜傷害。',
        '공격형 소환수 룬. 전기 구체 모양의 번개 위습 정령을 소환합니다. 위습이 대상에게 전류를 흘려 감전시키는 번개 피해를 줍니다.': '攻擊型召喚符文。召喚電球形狀的閃電鬼火精靈。鬼火向目標輸送電流，造成使其感電的閃電傷害。',
        '공격형 소환수 룬. 고목 씨앗 모양의 물리 위습 정령을 소환합니다. 위습이 땅속으로 뿌리를 보내 대상을 옭아매는 물리 피해를 줍니다.': '攻擊型召喚符文。召喚古樹種子形狀的物理鬼火精靈。鬼火向地下伸出根鬚纏住目標，造成物理傷害。',
        '공격형 소환수 룬. 눈이 하나 있는 보라빛 구체의 카오스 위습 정령을 소환합니다. 위습이 공허 구슬을 포물선으로 던지고 떨어진 자리에 카오스 안개를 남깁니다.': '攻擊型召喚符文。召喚獨眼紫色球體的混沌鬼火精靈。鬼火以拋物線投擲虛空珠，並在落點留下混沌霧氣。',
        '소환 한도 1을 사용합니다. 수액 골렘이 살아 있는 동안 최종 적중 피해의 35%를 대신 받습니다. 지속 피해는 대신 받지 않습니다.': '佔用1個召喚上限。樹液魔像存活期間，代替承受最終命中傷害的35%。不代替承受持續傷害。',
