        '{name} (초월)': '{name}（超越）',
        '요정의 고리는 옵션이 있는 공허 패시브에만 쓸 수 있습니다. 마법의 새싹으로 먼저 옵션을 굴리세요.': '妖精之環只能用於帶有詞綴的虛空被動。請先用魔法新芽擲出詞綴。',
        '이 소켓에는 이번 루프에 요정의 고리를 다시 쓸 수 없습니다.': '本次循環無法再對此插槽使用妖精之環。',
        '🌌 공허 패시브 초월: {replace}': '🌌 虛空被動超越：{replace}',
        '💥 요정의 고리: 초월에 실패해 공허 패시브의 옵션이 지워졌습니다.': '💥 妖精之環：超越失敗，虛空被動的詞綴已被清除。',
        '🌊 리프트도 가디언 처치도 물고기도 없이 {limit}번 떠올라 자동 재잠수를 멈춥니다. 잠수 시작을 누르면 다시 이어집니다.': '🌊 在沒有升降、沒有擊倒守護者、沒有魚的情況下上浮{limit}次，自動再次潛水停止。按開始潛水可繼續。',
        '🌊 자동 재잠수는 {lift}m부터 내려가 물고기를 모읍니다.': '🌊 自動再次潛水將從{lift}m下潛收集魚。',
        '심연의 보스 학살': '深淵屠Boss',
        '보스에게 가하는 피해가 증가합니다. (일반 옵션으로는 등장하지 않는 전용 스탯)': '提高對Boss造成的傷害。（不會作為普通詞綴出現的專屬屬性）',
